25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * IP ethernet frame transmitter (IP frame in, Ethernet frame out)
33	 */
34	module ip_eth_tx
35	(
36	    input  wire        clk,
37	    input  wire        rst,
38	
39	    /*
40	     * IP frame input
41	     */
42	    input  wire        s_ip_hdr_valid,
43	    output wire        s_ip_hdr_ready,
44	    input  wire [47:0] s_eth_dest_mac,
45	    input  wire [47:0] s_eth_src_mac,
46	    input  wire [15:0] s_eth_type,
47	    input  wire [5:0]  s_ip_dscp,
48	    input  wire [1:0]  s_ip_ecn,
49	    input  wire [15:0] s_ip_length,
50	    input  wire [15:0] s_ip_identification,
51	    input  wire [2:0]  s_ip_flags,
52	    input  wire [12:0] s_ip_fragment_offset,
53	    input  wire [7:0]  s_ip_ttl,
54	    input  wire [7:0]  s_ip_protocol,
55	    input  wire [31:0] s_ip_source_ip,
56	    input  wire [31:0] s_ip_dest_ip,
57	    input  wire [7:0]  s_ip_payload_axis_tdata,
58	    input  wire        s_ip_payload_axis_tvalid,
59	    output wire        s_ip_payload_axis_tready,
60	    input  wire        s_ip_payload_axis_tlast,
61	    input  wire        s_ip_payload_axis_tuser,
62	
63	    /*
64	     * Ethernet frame output
65	     */
66	    output wire        m_eth_hdr_valid,
67	    input  wire        m_eth_hdr_ready,
68	    output wire [47:0] m_eth_dest_mac,
69	    output wire [47:0] m_eth_src_mac,
70	    output wire [15:0] m_eth_type,
71	    output wire [7:0]  m_eth_payload_axis_tdata,
72	    output wire        m_eth_payload_axis_tvalid,
73	    input  wire        m_eth_payload_axis_tready,
74	    output wire        m_eth_payload_axis_tlast,
75	    output wire        m_eth_payload_axis_tuser,
76	
77	    /*
78	     * Status signals
79	     */
80	    output wire        busy,
81	    output wire        error_payload_early_termination
82	);
83	
84	/*
85	
86	IP Frame
87	
88	 Field                       Length
89	 Destination MAC address     6 octets
90	 Source MAC address          6 octets
91	 Ethertype (0x0800)          2 octets
92	 Version (4)                 4 bits
93	 IHL (5-15)                  4 bits
94	 DSCP (0)                    6 bits
95	 ECN (0)                     2 bits
96	 length                      2 octets
97	 identification (0?)         2 octets
98	 flags (010)                 3 bits
99	 fragment offset (0)         13 bits
100	 time to live (64?)          1 octet
101	 protocol                    1 octet
102	 header checksum             2 octets
103	 source IP                   4 octets
104	 destination IP              4 octets
105	 options                     (IHL-5)*4 octets
106	 payload                     length octets
107	
108	This module receives an IP frame with header fields in parallel along with the
109	payload in an AXI stream, combines the header with the payload, passes through
110	the Ethernet headers, and transmits the complete Ethernet payload on an AXI
111	interface.
112	
113	*/
114	
115	localparam [2:0]
116	    STATE_IDLE = 3'd0,
117	    STATE_WRITE_HEADER = 3'd1,
118	    STATE_WRITE_PAYLOAD = 3'd2,
119	    STATE_WRITE_PAYLOAD_LAST = 3'd3,
120	    STATE_WAIT_LAST = 3'd4;
121	
122	reg [2:0] state_reg = STATE_IDLE, state_next;
123	
124	// datapath control signals
125	reg store_ip_hdr;
126	reg store_last_word;
127	
128	reg [5:0] hdr_ptr_reg = 6'd0, hdr_ptr_next;
129	reg [15:0] word_count_reg = 16'd0, word_count_next;
130	
131	reg [15:0] hdr_sum_reg = 16'd0, hdr_sum_next;
132	
133	reg [7:0] last_word_data_reg = 8'd0;
134	
135	reg [5:0] ip_dscp_reg = 6'd0;
136	reg [1:0] ip_ecn_reg = 2'd0;
137	reg [15:0] ip_length_reg = 16'd0;
138	reg [15:0] ip_identification_reg = 16'd0;
139	reg [2:0] ip_flags_reg = 3'd0;
140	reg [12:0] ip_fragment_offset_reg = 13'd0;
141	reg [7:0] ip_ttl_reg = 8'd0;
142	reg [7:0] ip_protocol_reg = 8'd0;
143	reg [31:0] ip_source_ip_reg = 32'd0;
144	reg [31:0] ip_dest_ip_reg = 32'd0;
145	
146	reg s_ip_hdr_ready_reg = 1'b0, s_ip_hdr_ready_next;
147	reg s_ip_payload_axis_tready_reg = 1'b0, s_ip_payload_axis_tready_next;
148	
149	reg m_eth_hdr_valid_reg = 1'b0, m_eth_hdr_valid_next;
150	reg [47:0] m_eth_dest_mac_reg = 48'd0;
151	reg [47:0] m_eth_src_mac_reg = 48'd0;
152	reg [15:0] m_eth_type_reg = 16'd0;
153	
154	reg busy_reg = 1'b0;
155	reg error_payload_early_termination_reg = 1'b0, error_payload_early_termination_next;
156	
157	// internal datapath
158	reg [7:0] m_eth_payload_axis_tdata_int;
159	reg       m_eth_payload_axis_tvalid_int;
160	reg       m_eth_payload_axis_tready_int_reg = 1'b0;
161	reg       m_eth_payload_axis_tlast_int;
162	reg       m_eth_payload_axis_tuser_int;
163	wire      m_eth_payload_axis_tready_int_early;
164	
165	assign s_ip_hdr_ready = s_ip_hdr_ready_reg;
166	assign s_ip_payload_axis_tready = s_ip_payload_axis_tready_reg;
167	
168	assign m_eth_hdr_valid = m_eth_hdr_valid_reg;
169	assign m_eth_dest_mac = m_eth_dest_mac_reg;
170	assign m_eth_src_mac = m_eth_src_mac_reg;
171	assign m_eth_type = m_eth_type_reg;
172	
173	assign busy = busy_reg;
174	assign error_payload_early_termination = error_payload_early_termination_reg;
175	
176	function [15:0] add1c16b;
177	    input [15:0] a, b;
178	    reg [16:0] t;
179	    begin
180	        t = a+b;
181	        add1c16b = t[15:0] + t[16];
182	    end
183	endfunction
184	
185	always @* begin
186	    state_next = STATE_IDLE;
187	
188	    s_ip_hdr_ready_next = 1'b0;
189	    s_ip_payload_axis_tready_next = 1'b0;
190	
191	    store_ip_hdr = 1'b0;
192	
193	    store_last_word = 1'b0;
194	
195	    hdr_ptr_next = hdr_ptr_reg;
196	    word_count_next = word_count_reg;
197	
198	    hdr_sum_next = hdr_sum_reg;
199	
200	    m_eth_hdr_valid_next = m_eth_hdr_valid_reg && !m_eth_hdr_ready;
201	
202	    error_payload_early_termination_next = 1'b0;
203	
204	    m_eth_payload_axis_tdata_int = 8'd0;
205	    m_eth_payload_axis_tvalid_int = 1'b0;
206	    m_eth_payload_axis_tlast_int = 1'b0;
207	    m_eth_payload_axis_tuser_int = 1'b0;
208	
209	    case (state_reg)
210	        STATE_IDLE: begin
211	            // idle state - wait for data
212	            hdr_ptr_next = 6'd0;
213	            s_ip_hdr_ready_next = !m_eth_hdr_valid_next;
214	
215	            if (s_ip_hdr_ready && s_ip_hdr_valid) begin
216	                store_ip_hdr = 1'b1;
217	                s_ip_hdr_ready_next = 1'b0;
218	                m_eth_hdr_valid_next = 1'b1;
219	                if (m_eth_payload_axis_tready_int_reg) begin
220	                    m_eth_payload_axis_tvalid_int = 1'b1;
221	                    m_eth_payload_axis_tdata_int = {4'd4, 4'd5}; // ip_version, ip_ihl
222	                    hdr_ptr_next = 6'd1;
223	                end
224	                state_next = STATE_WRITE_HEADER;
225	            end else begin
226	                state_next = STATE_IDLE;
227	            end
228	        end
229	        STATE_WRITE_HEADER: begin
230	            // write header
231	            word_count_next = ip_length_reg - 5*4;
232	
233	            if (m_eth_payload_axis_tready_int_reg) begin
234	                hdr_ptr_next = hdr_ptr_reg + 6'd1;
235	                m_eth_payload_axis_tvalid_int = 1;
236	                state_next = STATE_WRITE_HEADER;
237	                case (hdr_ptr_reg)
238	                    6'h00: begin
239	                        m_eth_payload_axis_tdata_int = {4'd4, 4'd5}; // ip_version, ip_ihl
240	                    end
241	                    6'h01: begin
242	                        m_eth_payload_axis_tdata_int = {ip_dscp_reg, ip_ecn_reg};
243	                        hdr_sum_next = {4'd4, 4'd5, ip_dscp_reg, ip_ecn_reg};
244	                    end
245	                    6'h02: begin
246	                        m_eth_payload_axis_tdata_int = ip_length_reg[15: 8];
247	                        hdr_sum_next = add1c16b(hdr_sum_reg, ip_length_reg);
248	                    end
249	                    6'h03: begin
250	                        m_eth_payload_axis_tdata_int = ip_length_reg[ 7: 0];
251	                        hdr_sum_next = add1c16b(hdr_sum_reg, ip_identification_reg);
252	                    end
253	                    6'h04: begin
254	                        m_eth_payload_axis_tdata_int = ip_identification_reg[15: 8];
255	                        hdr_sum_next = add1c16b(hdr_sum_reg, {ip_flags_reg, ip_fragment_offset_reg});
256	                    end
257	                    6'h05: begin
258	                        m_eth_payload_axis_tdata_int = ip_identification_reg[ 7: 0];
259	                        hdr_sum_next = add1c16b(hdr_sum_reg, {ip_ttl_reg, ip_protocol_reg});
260	                    end
261	                    6'h06: begin
262	                        m_eth_payload_axis_tdata_int = {ip_flags_reg, ip_fragment_offset_reg[12:8]};
263	                        hdr_sum_next = add1c16b(hdr_sum_reg, ip_source_ip_reg[31:16]);
264	                    end
265	                    6'h07: begin
266	                        m_eth_payload_axis_tdata_int = ip_fragment_offset_reg[ 7: 0];
267	                        hdr_sum_next = add1c16b(hdr_sum_reg, ip_source_ip_reg[15:0]);
268	                    end
269	                    6'h08: begin
270	                        m_eth_payload_axis_tdata_int = ip_ttl_reg;
271	                        hdr_sum_next = add1c16b(hdr_sum_reg, ip_dest_ip_reg[31:16]);
272	                    end
273	                    6'h09: begin
274	                        m_eth_payload_axis_tdata_int = ip_protocol_reg;
275	                        hdr_sum_next = add1c16b(hdr_sum_reg, ip_dest_ip_reg[15:0]);
276	                    end
277	                    6'h0A: m_eth_payload_axis_tdata_int = ~hdr_sum_reg[15: 8];
278	                    6'h0B: m_eth_payload_axis_tdata_int = ~hdr_sum_reg[ 7: 0];
279	                    6'h0C: m_eth_payload_axis_tdata_int = ip_source_ip_reg[31:24];
280	                    6'h0D: m_eth_payload_axis_tdata_int = ip_source_ip_reg[23:16];
281	                    6'h0E: m_eth_payload_axis_tdata_int = ip_source_ip_reg[15: 8];
282	                    6'h0F: m_eth_payload_axis_tdata_int = ip_source_ip_reg[ 7: 0];
283	                    6'h10: m_eth_payload_axis_tdata_int = ip_dest_ip_reg[31:24];
284	                    6'h11: m_eth_payload_axis_tdata_int = ip_dest_ip_reg[23:16];
285	                    6'h12: m_eth_payload_axis_tdata_int = ip_dest_ip_reg[15: 8];
286	                    6'h13: begin
287	                        m_eth_payload_axis_tdata_int = ip_dest_ip_reg[ 7: 0];
288	                        s_ip_payload_axis_tready_next = m_eth_payload_axis_tready_int_early;
289	                        state_next = STATE_WRITE_PAYLOAD;
290	                    end
291	                endcase
292	            end else begin
293	                state_next = STATE_WRITE_HEADER;
294	            end
295	        end
296	        STATE_WRITE_PAYLOAD: begin
297	            // write payload
298	            s_ip_payload_axis_tready_next = m_eth_payload_axis_tready_int_early;
299	
300	            m_eth_payload_axis_tdata_int = s_ip_payload_axis_tdata;
301	            m_eth_payload_axis_tlast_int = s_ip_payload_axis_tlast;
302	            m_eth_payload_axis_tuser_int = s_ip_payload_axis_tuser;
303	
304	            if (s_ip_payload_axis_tready && s_ip_payload_axis_tvalid) begin
305	                // word transfer through
306	                word_count_next = word_count_reg - 6'd1;
307	                m_eth_payload_axis_tvalid_int = 1'b1;
308	                if (s_ip_payload_axis_tlast) begin
309	                    if (word_count_reg != 16'd1) begin
310	                        // end of frame, but length does not match
311	                        m_eth_payload_axis_tuser_int = 1'b1;
312	                        error_payload_early_termination_next = 1'b1;
313	                    end
314	                    s_ip_hdr_ready_next = !m_eth_hdr_valid_next;
315	                    s_ip_payload_axis_tready_next = 1'b0;
316	                    state_next = STATE_IDLE;
317	                end else begin
318	                    if (word_count_reg == 16'd1) begin
319	                        store_last_word = 1'b1;
320	                        m_eth_payload_axis_tvalid_int = 1'b0;
321	                        state_next = STATE_WRITE_PAYLOAD_LAST;
322	                    end else begin
323	                        state_next = STATE_WRITE_PAYLOAD;
324	                    end
325	                end
326	            end else begin
327	                state_next = STATE_WRITE_PAYLOAD;
328	            end
329	        end
330	        STATE_WRITE_PAYLOAD_LAST: begin
331	            // read and discard until end of frame
332	            s_ip_payload_axis_tready_next = m_eth_payload_axis_tready_int_early;
333	
334	            m_eth_payload_axis_tdata_int = last_word_data_reg;
335	            m_eth_payload_axis_tlast_int = s_ip_payload_axis_tlast;
336	            m_eth_payload_axis_tuser_int = s_ip_payload_axis_tuser;
337	
338	            if (s_ip_payload_axis_tready && s_ip_payload_axis_tvalid) begin
339	                if (s_ip_payload_axis_tlast) begin
340	                    s_ip_hdr_ready_next = !m_eth_hdr_valid_next;
341	                    s_ip_payload_axis_tready_next = 1'b0;
342	                    m_eth_payload_axis_tvalid_int = 1'b1;
343	                    state_next = STATE_IDLE;
344	                end else begin
345	                    state_next = STATE_WRITE_PAYLOAD_LAST;
346	                end
347	            end else begin
348	                state_next = STATE_WRITE_PAYLOAD_LAST;
349	            end
350	        end
351	        STATE_WAIT_LAST: begin
352	            // read and discard until end of frame
353	            s_ip_payload_axis_tready_next = 1'b1;
354	
355	            if (s_ip_payload_axis_tready && s_ip_payload_axis_tvalid) begin
356	                if (s_ip_payload_axis_tlast) begin
357	                    s_ip_hdr_ready_next = !m_eth_hdr_valid_next;
358	                    s_ip_payload_axis_tready_next = 1'b0;
359	                    state_next = STATE_IDLE;
360	                end else begin
361	                    state_next = STATE_WAIT_LAST;
362	                end
363	            end else begin
364	                state_next = STATE_WAIT_LAST;
365	            end
366	        end
367	    endcase
368	end
369	
370	always @(posedge clk) begin
371	    if (rst) begin
372	        state_reg <= STATE_IDLE;
373	        s_ip_hdr_ready_reg <= 1'b0;
374	        s_ip_payload_axis_tready_reg <= 1'b0;
375	        m_eth_hdr_valid_reg <= 1'b0;
376	        busy_reg <= 1'b0;
377	        error_payload_early_termination_reg <= 1'b0;
378	    end else begin
379	        state_reg <= state_next;
380	
381	        s_ip_hdr_ready_reg <= s_ip_hdr_ready_next;
382	        s_ip_payload_axis_tready_reg <= s_ip_payload_axis_tready_next;
383	
384	        m_eth_hdr_valid_reg <= m_eth_hdr_valid_next;
385	
386	        busy_reg <= state_next != STATE_IDLE;
387	
388	        error_payload_early_termination_reg <= error_payload_early_termination_next;
389	    end
390	
391	    hdr_ptr_reg <= hdr_ptr_next;
392	    word_count_reg <= word_count_next;
393	
394	    hdr_sum_reg <= hdr_sum_next;
395	
396	    // datapath
397	    if (store_ip_hdr) begin
398	        m_eth_dest_mac_reg <= s_eth_dest_mac;
399	        m_eth_src_mac_reg <= s_eth_src_mac;
400	        m_eth_type_reg <= s_eth_type;
401	        ip_dscp_reg <= s_ip_dscp;
402	        ip_ecn_reg <= s_ip_ecn;
403	        ip_length_reg <= s_ip_length;
404	        ip_identification_reg <= s_ip_identification;
405	        ip_flags_reg <= s_ip_flags;
406	        ip_fragment_offset_reg <= s_ip_fragment_offset;
407	        ip_ttl_reg <= s_ip_ttl;
408	        ip_protocol_reg <= s_ip_protocol;
409	        ip_source_ip_reg <= s_ip_source_ip;
410	        ip_dest_ip_reg <= s_ip_dest_ip;
411	    end
412	
413	    if (store_last_word) begin
414	        last_word_data_reg <= m_eth_payload_axis_tdata_int;
415	    end
416	end
417	
418	// output datapath logic
419	reg [7:0] m_eth_payload_axis_tdata_reg = 8'd0;
420	reg       m_eth_payload_axis_tvalid_reg = 1'b0, m_eth_payload_axis_tvalid_next;
421	reg       m_eth_payload_axis_tlast_reg = 1'b0;
422	reg       m_eth_payload_axis_tuser_reg = 1'b0;
423	
424	reg [7:0] temp_m_eth_payload_axis_tdata_reg = 8'd0;
425	reg       temp_m_eth_payload_axis_tvalid_reg = 1'b0, temp_m_eth_payload_axis_tvalid_next;
426	reg       temp_m_eth_payload_axis_tlast_reg = 1'b0;
427	reg       temp_m_eth_payload_axis_tuser_reg = 1'b0;
428	
429	// datapath control
430	reg store_eth_payload_int_to_output;
431	reg store_eth_payload_int_to_temp;
432	reg store_eth_payload_axis_temp_to_output;
433	
434	assign m_eth_payload_axis_tdata = m_eth_payload_axis_tdata_reg;
435	assign m_eth_payload_axis_tvalid = m_eth_payload_axis_tvalid_reg;
436	assign m_eth_payload_axis_tlast = m_eth_payload_axis_tlast_reg;
437	assign m_eth_payload_axis_tuser = m_eth_payload_axis_tuser_reg;
438	
439	// enable ready input next cycle if output is ready or if both output registers are empty
440	assign m_eth_payload_axis_tready_int_early = m_eth_payload_axis_tready || (!temp_m_eth_payload_axis_tvalid_reg && !m_eth_payload_axis_tvalid_reg);
441	
442	always @* begin
443	    // transfer sink ready state to source
444	    m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_reg;
445	    temp_m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
446	
447	    store_eth_payload_int_to_output = 1'b0;
448	    store_eth_payload_int_to_temp = 1'b0;
449	    store_eth_payload_axis_temp_to_output = 1'b0;
450	    
451	    if (m_eth_payload_axis_tready_int_reg) begin
452	        // input is ready
453	        if (m_eth_payload_axis_tready || !m_eth_payload_axis_tvalid_reg) begin
454	            // output is ready or currently not valid, transfer data to output
455	            m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
456	            store_eth_payload_int_to_output = 1'b1;
457	        end else begin
458	            // output is not ready, store input in temp
459	            temp_m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
460	            store_eth_payload_int_to_temp = 1'b1;
461	        end
462	    end else if (m_eth_payload_axis_tready) begin
463	        // input is not ready, but output is ready
464	        m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
465	        temp_m_eth_payload_axis_tvalid_next = 1'b0;
466	        store_eth_payload_axis_temp_to_output = 1'b1;
467	    end
468	end
469	
470	always @(posedge clk) begin
471	    m_eth_payload_axis_tvalid_reg <= m_eth_payload_axis_tvalid_next;
472	    m_eth_payload_axis_tready_int_reg <= m_eth_payload_axis_tready_int_early;
473	    temp_m_eth_payload_axis_tvalid_reg <= temp_m_eth_payload_axis_tvalid_next;
474	
475	    // datapath
476	    if (store_eth_payload_int_to_output) begin
477	        m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
478	        m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
479	        m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
480	    end else if (store_eth_payload_axis_temp_to_output) begin
481	        m_eth_payload_axis_tdata_reg <= temp_m_eth_payload_axis_tdata_reg;
482	        m_eth_payload_axis_tlast_reg <= temp_m_eth_payload_axis_tlast_reg;
483	        m_eth_payload_axis_tuser_reg <= temp_m_eth_payload_axis_tuser_reg;
484	    end
485	
486	    if (store_eth_payload_int_to_temp) begin
487	        temp_m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
488	        temp_m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
489	        temp_m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
490	    end
491	
492	    if (rst) begin
493	        m_eth_payload_axis_tvalid_reg <= 1'b0;
494	        m_eth_payload_axis_tready_int_reg <= 1'b0;
495	        temp_m_eth_payload_axis_tvalid_reg <= 1'b0;
496	    end
497	end
498	
499	endmodule
500	
501	`resetall
502

