31	/*
32	 * IP ethernet frame receiver (Ethernet frame in, IP frame out)
33	 */
34	module ip_eth_rx
35	(
36	    input  wire        clk,
37	    input  wire        rst,
38	
39	    /*
40	     * Ethernet frame input
41	     */
42	    input  wire        s_eth_hdr_valid,
43	    output wire        s_eth_hdr_ready,
44	    input  wire [47:0] s_eth_dest_mac,
45	    input  wire [47:0] s_eth_src_mac,
46	    input  wire [15:0] s_eth_type,
47	    input  wire [7:0]  s_eth_payload_axis_tdata,
48	    input  wire        s_eth_payload_axis_tvalid,
49	    output wire        s_eth_payload_axis_tready,
50	    input  wire        s_eth_payload_axis_tlast,
51	    input  wire        s_eth_payload_axis_tuser,
52	
53	    /*
54	     * IP frame output
55	     */
56	    output wire        m_ip_hdr_valid,
57	    input  wire        m_ip_hdr_ready,
58	    output wire [47:0] m_eth_dest_mac,
59	    output wire [47:0] m_eth_src_mac,
60	    output wire [15:0] m_eth_type,
61	    output wire [3:0]  m_ip_version,
62	    output wire [3:0]  m_ip_ihl,
63	    output wire [5:0]  m_ip_dscp,
64	    output wire [1:0]  m_ip_ecn,
65	    output wire [15:0] m_ip_length,
66	    output wire [15:0] m_ip_identification,
67	    output wire [2:0]  m_ip_flags,
68	    output wire [12:0] m_ip_fragment_offset,
69	    output wire [7:0]  m_ip_ttl,
70	    output wire [7:0]  m_ip_protocol,
71	    output wire [15:0] m_ip_header_checksum,
72	    output wire [31:0] m_ip_source_ip,
73	    output wire [31:0] m_ip_dest_ip,
74	    output wire [7:0]  m_ip_payload_axis_tdata,
75	    output wire        m_ip_payload_axis_tvalid,
76	    input  wire        m_ip_payload_axis_tready,
77	    output wire        m_ip_payload_axis_tlast,
78	    output wire        m_ip_payload_axis_tuser,
79	
80	    /*
81	     * Status signals
82	     */
83	    output wire        busy,
84	    output wire        error_header_early_termination,
85	    output wire        error_payload_early_termination,
86	    output wire        error_invalid_header,
87	    output wire        error_invalid_checksum
88	);
89	
90	/*
91	
92	IP Frame
93	
94	 Field                       Length
95	 Destination MAC address     6 octets
96	 Source MAC address          6 octets
97	 Ethertype (0x0800)          2 octets
98	 Version (4)                 4 bits
99	 IHL (5-15)                  4 bits
100	 DSCP (0)                    6 bits
101	 ECN (0)                     2 bits
102	 length                      2 octets
103	 identification (0?)         2 octets
104	 flags (010)                 3 bits
105	 fragment offset (0)         13 bits
106	 time to live (64?)          1 octet
107	 protocol                    1 octet
108	 header checksum             2 octets
109	 source IP                   4 octets
110	 destination IP              4 octets
111	 options                     (IHL-5)*4 octets
112	 payload                     length octets
113	
114	This module receives an Ethernet frame with header fields in parallel and
115	payload on an AXI stream interface, decodes and strips the IP header fields,
116	then produces the header fields in parallel along with the IP payload in a
117	separate AXI stream.
118	
119	*/
120	
121	localparam [2:0]
