132	reg store_ip_version_ihl;
133	reg store_ip_dscp_ecn;
134	reg store_ip_length_0;
135	reg store_ip_length_1;
136	reg store_ip_identification_0;
137	reg store_ip_identification_1;
138	reg store_ip_flags_fragment_offset_0;
139	reg store_ip_flags_fragment_offset_1;
140	reg store_ip_ttl;
141	reg store_ip_protocol;
142	reg store_ip_header_checksum_0;
143	reg store_ip_header_checksum_1;
144	reg store_ip_source_ip_0;
145	reg store_ip_source_ip_1;
146	reg store_ip_source_ip_2;
147	reg store_ip_source_ip_3;
148	reg store_ip_dest_ip_0;
149	reg store_ip_dest_ip_1;
150	reg store_ip_dest_ip_2;
151	reg store_ip_dest_ip_3;
152	reg store_last_word;
