161	reg s_eth_hdr_ready_reg = 1'b0, s_eth_hdr_ready_next;
162	reg s_eth_payload_axis_tready_reg = 1'b0, s_eth_payload_axis_tready_next;
163	
164	reg m_ip_hdr_valid_reg = 1'b0, m_ip_hdr_valid_next;
165	reg [47:0] m_eth_dest_mac_reg = 48'd0;
166	reg [47:0] m_eth_src_mac_reg = 48'd0;
167	reg [15:0] m_eth_type_reg = 16'd0;
168	reg [3:0] m_ip_version_reg = 4'd0;
169	reg [3:0] m_ip_ihl_reg = 4'd0;
170	reg [5:0] m_ip_dscp_reg = 6'd0;
171	reg [1:0] m_ip_ecn_reg = 2'd0;
172	reg [15:0] m_ip_length_reg = 16'd0;
173	reg [15:0] m_ip_identification_reg = 16'd0;
174	reg [2:0] m_ip_flags_reg = 3'd0;
175	reg [12:0] m_ip_fragment_offset_reg = 13'd0;
176	reg [7:0] m_ip_ttl_reg = 8'd0;
177	reg [7:0] m_ip_protocol_reg = 8'd0;
178	reg [15:0] m_ip_header_checksum_reg = 16'd0;
179	reg [31:0] m_ip_source_ip_reg = 32'd0;
180	reg [31:0] m_ip_dest_ip_reg = 32'd0;
181	
182	reg busy_reg = 1'b0;
183	reg error_header_early_termination_reg = 1'b0, error_header_early_termination_next;
184	reg error_payload_early_termination_reg = 1'b0, error_payload_early_termination_next;
185	reg error_invalid_header_reg = 1'b0, error_invalid_header_next;
186	reg error_invalid_checksum_reg = 1'b0, error_invalid_checksum_next;
