189	reg [7:0] m_ip_payload_axis_tdata_int;
190	reg       m_ip_payload_axis_tvalid_int;
191	reg       m_ip_payload_axis_tready_int_reg = 1'b0;
192	reg       m_ip_payload_axis_tlast_int;
193	reg       m_ip_payload_axis_tuser_int;
194	wire      m_ip_payload_axis_tready_int_early;
