197	assign s_eth_payload_axis_tready = s_eth_payload_axis_tready_reg;
198	
199	assign m_ip_hdr_valid = m_ip_hdr_valid_reg;
200	assign m_eth_dest_mac = m_eth_dest_mac_reg;
201	assign m_eth_src_mac = m_eth_src_mac_reg;
202	assign m_eth_type = m_eth_type_reg;
203	assign m_ip_version = m_ip_version_reg;
204	assign m_ip_ihl = m_ip_ihl_reg;
205	assign m_ip_dscp = m_ip_dscp_reg;
206	assign m_ip_ecn = m_ip_ecn_reg;
207	assign m_ip_length = m_ip_length_reg;
208	assign m_ip_identification = m_ip_identification_reg;
209	assign m_ip_flags = m_ip_flags_reg;
210	assign m_ip_fragment_offset = m_ip_fragment_offset_reg;
211	assign m_ip_ttl = m_ip_ttl_reg;
212	assign m_ip_protocol = m_ip_protocol_reg;
213	assign m_ip_header_checksum = m_ip_header_checksum_reg;
214	assign m_ip_source_ip = m_ip_source_ip_reg;
215	assign m_ip_dest_ip = m_ip_dest_ip_reg;
216	
217	assign busy = busy_reg;
218	assign error_header_early_termination = error_header_early_termination_reg;
219	assign error_payload_early_termination = error_payload_early_termination_reg;
220	assign error_invalid_header = error_invalid_header_reg;
221	assign error_invalid_checksum = error_invalid_checksum_reg;
