232	always @* begin
233	    state_next = STATE_IDLE;
234	
235	    s_eth_hdr_ready_next = 1'b0;
236	    s_eth_payload_axis_tready_next = 1'b0;
237	
238	    store_eth_hdr = 1'b0;
239	    store_ip_version_ihl = 1'b0;
240	    store_ip_dscp_ecn = 1'b0;
241	    store_ip_length_0 = 1'b0;
242	    store_ip_length_1 = 1'b0;
243	    store_ip_identification_0 = 1'b0;
244	    store_ip_identification_1 = 1'b0;
245	    store_ip_flags_fragment_offset_0 = 1'b0;
246	    store_ip_flags_fragment_offset_1 = 1'b0;
247	    store_ip_ttl = 1'b0;
248	    store_ip_protocol = 1'b0;
249	    store_ip_header_checksum_0 = 1'b0;
250	    store_ip_header_checksum_1 = 1'b0;
251	    store_ip_source_ip_0 = 1'b0;
252	    store_ip_source_ip_1 = 1'b0;
253	    store_ip_source_ip_2 = 1'b0;
254	    store_ip_source_ip_3 = 1'b0;
255	    store_ip_dest_ip_0 = 1'b0;
256	    store_ip_dest_ip_1 = 1'b0;
257	    store_ip_dest_ip_2 = 1'b0;
258	    store_ip_dest_ip_3 = 1'b0;
259	
260	    store_last_word = 1'b0;
261	
262	    hdr_ptr_next = hdr_ptr_reg;
263	    word_count_next = word_count_reg;
264	
265	    hdr_sum_next = hdr_sum_reg;
266	
267	    m_ip_hdr_valid_next = m_ip_hdr_valid_reg && !m_ip_hdr_ready;
268	
269	    error_header_early_termination_next = 1'b0;
270	    error_payload_early_termination_next = 1'b0;
271	    error_invalid_header_next = 1'b0;
272	    error_invalid_checksum_next = 1'b0;
273	
274	    m_ip_payload_axis_tdata_int = 8'd0;
275	    m_ip_payload_axis_tvalid_int = 1'b0;
276	    m_ip_payload_axis_tlast_int = 1'b0;
277	    m_ip_payload_axis_tuser_int = 1'b0;
278	
279	    case (state_reg)
280	        STATE_IDLE: begin
281	            // idle state - wait for header
282	            hdr_ptr_next = 16'd0;
283	            hdr_sum_next = 16'd0;
284	            s_eth_hdr_ready_next = !m_ip_hdr_valid_next;
285	
286	            if (s_eth_hdr_ready && s_eth_hdr_valid) begin
287	                s_eth_hdr_ready_next = 1'b0;
288	                s_eth_payload_axis_tready_next = 1'b1;
289	                store_eth_hdr = 1'b1;
290	                state_next = STATE_READ_HEADER;
291	            end else begin
292	                state_next = STATE_IDLE;
293	            end
294	        end
295	        STATE_READ_HEADER: begin
296	            // read header
297	            s_eth_payload_axis_tready_next = 1'b1;
298	            word_count_next = m_ip_length_reg - 5*4;
299	
300	            if (s_eth_payload_axis_tready && s_eth_payload_axis_tvalid) begin
301	                // word transfer in - store it
302	                hdr_ptr_next = hdr_ptr_reg + 6'd1;
303	                state_next = STATE_READ_HEADER;
304	
305	                if (hdr_ptr_reg[0]) begin
306	                    hdr_sum_next = add1c16b(hdr_sum_reg, {8'd0, s_eth_payload_axis_tdata});
307	                end else begin
308	                    hdr_sum_next = add1c16b(hdr_sum_reg, {s_eth_payload_axis_tdata, 8'd0});
309	                end
310	
311	                case (hdr_ptr_reg)
312	                    6'h00: store_ip_version_ihl = 1'b1;
313	                    6'h01: store_ip_dscp_ecn = 1'b1;
314	                    6'h02: store_ip_length_1 = 1'b1;
315	                    6'h03: store_ip_length_0 = 1'b1;
316	                    6'h04: store_ip_identification_1 = 1'b1;
317	                    6'h05: store_ip_identification_0 = 1'b1;
318	                    6'h06: store_ip_flags_fragment_offset_1 = 1'b1;
319	                    6'h07: store_ip_flags_fragment_offset_0 = 1'b1;
320	                    6'h08: store_ip_ttl = 1'b1;
321	                    6'h09: store_ip_protocol = 1'b1;
322	                    6'h0A: store_ip_header_checksum_1 = 1'b1;
323	                    6'h0B: store_ip_header_checksum_0 = 1'b1;
324	                    6'h0C: store_ip_source_ip_3 = 1'b1;
325	                    6'h0D: store_ip_source_ip_2 = 1'b1;
326	                    6'h0E: store_ip_source_ip_1 = 1'b1;
327	                    6'h0F: store_ip_source_ip_0 = 1'b1;
328	                    6'h10: store_ip_dest_ip_3 = 1'b1;
329	                    6'h11: store_ip_dest_ip_2 = 1'b1;
330	                    6'h12: store_ip_dest_ip_1 = 1'b1;
331	                    6'h13: begin
332	                        store_ip_dest_ip_0 = 1'b1;
333	                        if (m_ip_version_reg != 4'd4 || m_ip_ihl_reg != 4'd5) begin
334	                            error_invalid_header_next = 1'b1;
335	                            state_next = STATE_WAIT_LAST;
336	                        end else if (hdr_sum_next != 16'hffff) begin
337	                            error_invalid_checksum_next = 1'b1;
338	                            state_next = STATE_WAIT_LAST;
339	                        end else begin
340	                            m_ip_hdr_valid_next = 1'b1;
341	                            s_eth_payload_axis_tready_next = m_ip_payload_axis_tready_int_early;
342	                            state_next = STATE_READ_PAYLOAD;
343	                        end
344	                    end
345	                endcase
346	
347	                if (s_eth_payload_axis_tlast) begin
348	                    error_header_early_termination_next = 1'b1;
349	                    m_ip_hdr_valid_next = 1'b0;
350	                    s_eth_hdr_ready_next = !m_ip_hdr_valid_next;
351	                    s_eth_payload_axis_tready_next = 1'b0;
352	                    state_next = STATE_IDLE;
353	                end
354	
355	            end else begin
356	                state_next = STATE_READ_HEADER;
357	            end
358	        end
359	        STATE_READ_PAYLOAD: begin
360	            // read payload
361	            s_eth_payload_axis_tready_next = m_ip_payload_axis_tready_int_early;
362	
363	            m_ip_payload_axis_tdata_int = s_eth_payload_axis_tdata;
364	            m_ip_payload_axis_tlast_int = s_eth_payload_axis_tlast;
365	            m_ip_payload_axis_tuser_int = s_eth_payload_axis_tuser;
366	
367	            if (s_eth_payload_axis_tready && s_eth_payload_axis_tvalid) begin
368	                // word transfer through
369	                word_count_next = word_count_reg - 16'd1;
370	                m_ip_payload_axis_tvalid_int = 1'b1;
371	                if (s_eth_payload_axis_tlast) begin
372	                    if (word_count_reg > 16'd1) begin
373	                        // end of frame, but length does not match
374	                        m_ip_payload_axis_tuser_int = 1'b1;
375	                        error_payload_early_termination_next = 1'b1;
376	                    end
377	                    s_eth_hdr_ready_next = !m_ip_hdr_valid_next;
378	                    s_eth_payload_axis_tready_next = 1'b0;
379	                    state_next = STATE_IDLE;
380	                end else begin
381	                    if (word_count_reg == 16'd1) begin
382	                        store_last_word = 1'b1;
383	                        m_ip_payload_axis_tvalid_int = 1'b0;
384	                        state_next = STATE_READ_PAYLOAD_LAST;
385	                    end else begin
386	                        state_next = STATE_READ_PAYLOAD;
387	                    end
388	                end
389	            end else begin
390	                state_next = STATE_READ_PAYLOAD;
391	            end
392	        end
393	        STATE_READ_PAYLOAD_LAST: begin
394	            // read and discard until end of frame
395	            s_eth_payload_axis_tready_next = m_ip_payload_axis_tready_int_early;
396	
397	            m_ip_payload_axis_tdata_int = last_word_data_reg;
398	            m_ip_payload_axis_tlast_int = s_eth_payload_axis_tlast;
399	            m_ip_payload_axis_tuser_int = s_eth_payload_axis_tuser;
400	
401	            if (s_eth_payload_axis_tready && s_eth_payload_axis_tvalid) begin
402	                if (s_eth_payload_axis_tlast) begin
403	                    s_eth_hdr_ready_next = !m_ip_hdr_valid_next;
404	                    s_eth_payload_axis_tready_next = 1'b0;
405	                    m_ip_payload_axis_tvalid_int = 1'b1;
406	                    state_next = STATE_IDLE;
407	                end else begin
408	                    state_next = STATE_READ_PAYLOAD_LAST;
409	                end
410	            end else begin
411	                state_next = STATE_READ_PAYLOAD_LAST;
412	            end
413	        end
414	        STATE_WAIT_LAST: begin
415	            // read and discard until end of frame
416	            s_eth_payload_axis_tready_next = 1'b1;
417	
418	            if (s_eth_payload_axis_tready && s_eth_payload_axis_tvalid) begin
419	                if (s_eth_payload_axis_tlast) begin
420	                    s_eth_hdr_ready_next = !m_ip_hdr_valid_next;
421	                    s_eth_payload_axis_tready_next = 1'b0;
422	                    state_next = STATE_IDLE;
423	                end else begin
424	                    state_next = STATE_WAIT_LAST;
425	                end
426	            end else begin
427	                state_next = STATE_WAIT_LAST;
428	            end
429	        end
430	    endcase
431	end
