433	always @(posedge clk) begin
434	    if (rst) begin
435	        state_reg <= STATE_IDLE;
436	        s_eth_hdr_ready_reg <= 1'b0;
437	        s_eth_payload_axis_tready_reg <= 1'b0;
438	        m_ip_hdr_valid_reg <= 1'b0;
439	        busy_reg <= 1'b0;
440	        error_header_early_termination_reg <= 1'b0;
441	        error_payload_early_termination_reg <= 1'b0;
442	        error_invalid_header_reg <= 1'b0;
443	        error_invalid_checksum_reg <= 1'b0;
444	    end else begin
445	        state_reg <= state_next;
446	
447	        s_eth_hdr_ready_reg <= s_eth_hdr_ready_next;
448	        s_eth_payload_axis_tready_reg <= s_eth_payload_axis_tready_next;
449	
450	        m_ip_hdr_valid_reg <= m_ip_hdr_valid_next;
451	
452	        error_header_early_termination_reg <= error_header_early_termination_next;
453	        error_payload_early_termination_reg <= error_payload_early_termination_next;
454	        error_invalid_header_reg <= error_invalid_header_next;
455	        error_invalid_checksum_reg <= error_invalid_checksum_next;
456	
457	        busy_reg <= state_next != STATE_IDLE;
458	    end
459	
460	    hdr_ptr_reg <= hdr_ptr_next;
461	    word_count_reg <= word_count_next;
462	
463	    hdr_sum_reg <= hdr_sum_next;
464	
465	    // datapath
466	    if (store_eth_hdr) begin
467	        m_eth_dest_mac_reg <= s_eth_dest_mac;
468	        m_eth_src_mac_reg <= s_eth_src_mac;
469	        m_eth_type_reg <= s_eth_type;
470	    end
471	
472	    if (store_last_word) begin
473	        last_word_data_reg <= m_ip_payload_axis_tdata_int;
474	    end
475	
476	    if (store_ip_version_ihl) {m_ip_version_reg, m_ip_ihl_reg} <= s_eth_payload_axis_tdata;
477	    if (store_ip_dscp_ecn) {m_ip_dscp_reg, m_ip_ecn_reg} <= s_eth_payload_axis_tdata;
478	    if (store_ip_length_0) m_ip_length_reg[ 7: 0] <= s_eth_payload_axis_tdata;
479	    if (store_ip_length_1) m_ip_length_reg[15: 8] <= s_eth_payload_axis_tdata;
480	    if (store_ip_identification_0) m_ip_identification_reg[ 7: 0] <= s_eth_payload_axis_tdata;
481	    if (store_ip_identification_1) m_ip_identification_reg[15: 8] <= s_eth_payload_axis_tdata;
482	    if (store_ip_flags_fragment_offset_0) m_ip_fragment_offset_reg[ 7:0] <= s_eth_payload_axis_tdata;
483	    if (store_ip_flags_fragment_offset_1) {m_ip_flags_reg, m_ip_fragment_offset_reg[12:8]} <= s_eth_payload_axis_tdata;
484	    if (store_ip_ttl) m_ip_ttl_reg <= s_eth_payload_axis_tdata;
485	    if (store_ip_protocol) m_ip_protocol_reg <= s_eth_payload_axis_tdata;
486	    if (store_ip_header_checksum_0) m_ip_header_checksum_reg[ 7: 0] <= s_eth_payload_axis_tdata;
487	    if (store_ip_header_checksum_1) m_ip_header_checksum_reg[15: 8] <= s_eth_payload_axis_tdata;
488	    if (store_ip_source_ip_0) m_ip_source_ip_reg[ 7: 0] <= s_eth_payload_axis_tdata;
489	    if (store_ip_source_ip_1) m_ip_source_ip_reg[15: 8] <= s_eth_payload_axis_tdata;
490	    if (store_ip_source_ip_2) m_ip_source_ip_reg[23:16] <= s_eth_payload_axis_tdata;
491	    if (store_ip_source_ip_3) m_ip_source_ip_reg[31:24] <= s_eth_payload_axis_tdata;
492	    if (store_ip_dest_ip_0) m_ip_dest_ip_reg[ 7: 0] <= s_eth_payload_axis_tdata;
493	    if (store_ip_dest_ip_1) m_ip_dest_ip_reg[15: 8] <= s_eth_payload_axis_tdata;
494	    if (store_ip_dest_ip_2) m_ip_dest_ip_reg[23:16] <= s_eth_payload_axis_tdata;
495	    if (store_ip_dest_ip_3) m_ip_dest_ip_reg[31:24] <= s_eth_payload_axis_tdata;
496	end
497	
498	// output datapath logic
499	reg [7:0] m_ip_payload_axis_tdata_reg = 8'd0;
500	reg       m_ip_payload_axis_tvalid_reg = 1'b0, m_ip_payload_axis_tvalid_next;
501	reg       m_ip_payload_axis_tlast_reg = 1'b0;
502	reg       m_ip_payload_axis_tuser_reg = 1'b0;
503	
504	reg [7:0] temp_m_ip_payload_axis_tdata_reg = 8'd0;
505	reg       temp_m_ip_payload_axis_tvalid_reg = 1'b0, temp_m_ip_payload_axis_tvalid_next;
506	reg       temp_m_ip_payload_axis_tlast_reg = 1'b0;
507	reg       temp_m_ip_payload_axis_tuser_reg = 1'b0;
508	
509	// datapath control
510	reg store_ip_payload_int_to_output;
511	reg store_ip_payload_int_to_temp;
512	reg store_ip_payload_axis_temp_to_output;
513	
514	assign m_ip_payload_axis_tdata = m_ip_payload_axis_tdata_reg;
515	assign m_ip_payload_axis_tvalid = m_ip_payload_axis_tvalid_reg;
516	assign m_ip_payload_axis_tlast = m_ip_payload_axis_tlast_reg;
517	assign m_ip_payload_axis_tuser = m_ip_payload_axis_tuser_reg;
518	
519	// enable ready input next cycle if output is ready or if both output registers are empty
520	assign m_ip_payload_axis_tready_int_early = m_ip_payload_axis_tready || (!temp_m_ip_payload_axis_tvalid_reg && !m_ip_payload_axis_tvalid_reg);
521	
522	always @* begin
523	    // transfer sink ready state to source
524	    m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_reg;
525	    temp_m_ip_payload_axis_tvalid_next = temp_m_ip_payload_axis_tvalid_reg;
526	
527	    store_ip_payload_int_to_output = 1'b0;
528	    store_ip_payload_int_to_temp = 1'b0;
529	    store_ip_payload_axis_temp_to_output = 1'b0;
530	    
531	    if (m_ip_payload_axis_tready_int_reg) begin
532	        // input is ready
533	        if (m_ip_payload_axis_tready || !m_ip_payload_axis_tvalid_reg) begin
534	            // output is ready or currently not valid, transfer data to output
535	            m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_int;
536	            store_ip_payload_int_to_output = 1'b1;
537	        end else begin
538	            // output is not ready, store input in temp
539	            temp_m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_int;
540	            store_ip_payload_int_to_temp = 1'b1;
541	        end
542	    end else if (m_ip_payload_axis_tready) begin
543	        // input is not ready, but output is ready
544	        m_ip_payload_axis_tvalid_next = temp_m_ip_payload_axis_tvalid_reg;
545	        temp_m_ip_payload_axis_tvalid_next = 1'b0;
546	        store_ip_payload_axis_temp_to_output = 1'b1;
547	    end
548	end
549	
550	always @(posedge clk) begin
551	    m_ip_payload_axis_tvalid_reg <= m_ip_payload_axis_tvalid_next;
552	    m_ip_payload_axis_tready_int_reg <= m_ip_payload_axis_tready_int_early;
553	    temp_m_ip_payload_axis_tvalid_reg <= temp_m_ip_payload_axis_tvalid_next;
554	
555	    // datapath
556	    if (store_ip_payload_int_to_output) begin
557	        m_ip_payload_axis_tdata_reg <= m_ip_payload_axis_tdata_int;
558	        m_ip_payload_axis_tlast_reg <= m_ip_payload_axis_tlast_int;
559	        m_ip_payload_axis_tuser_reg <= m_ip_payload_axis_tuser_int;
560	    end else if (store_ip_payload_axis_temp_to_output) begin
561	        m_ip_payload_axis_tdata_reg <= temp_m_ip_payload_axis_tdata_reg;
562	        m_ip_payload_axis_tlast_reg <= temp_m_ip_payload_axis_tlast_reg;
563	        m_ip_payload_axis_tuser_reg <= temp_m_ip_payload_axis_tuser_reg;
564	    end
565	
566	    if (store_ip_payload_int_to_temp) begin
567	        temp_m_ip_payload_axis_tdata_reg <= m_ip_payload_axis_tdata_int;
568	        temp_m_ip_payload_axis_tlast_reg <= m_ip_payload_axis_tlast_int;
569	        temp_m_ip_payload_axis_tuser_reg <= m_ip_payload_axis_tuser_int;
570	    end
571	
572	    if (rst) begin
573	        m_ip_payload_axis_tvalid_reg <= 1'b0;
574	        m_ip_payload_axis_tready_int_reg <= 1'b0;
575	        temp_m_ip_payload_axis_tvalid_reg <= 1'b0;
576	    end
577	end
578	
579	endmodule
580	
581	`resetall
582

